    d.append(node('p',task.recovery.message,'pending'));
  if (task.action === 'qrcode' && task.status === 'unknown' && !task.interaction)
    d.append(node('p','远端可能已完成上传。请先核实结果；再次生成可能上传新版本。','pending'));
