// src/maker/index.ts
init_proxyPolicy();
init_lifecycle();
installCrashLogging();
async function main() {
  const command = process.argv[2];
  if (command === "__maker-console-server") {
    await runConsoleSupervisor();
    return;
  }
  if (command === "__maker-preview-supervisor") {
    await runPreviewSupervisor(previewProject(process.argv[3] || ""), process.argv[4]);
    return;
  }
  if (!command) {
    await startMakerMcpServer();
    return;
  }
  if (command === "__maker-proxy") {
    process.argv.splice(2, 1);
    await startEmbeddedProxy();
    return;
  }
  if (command === "help" || command === "--help" || command === "-h") {
    printHelp2();
    return;
  }
  await runMakerCli(process.argv.slice(2));
}
async function startEmbeddedProxy() {
  const config2 = await loadConfig();
  const proxy = new TapTapMCPProxy(config2, MAKER_PROXY_RUNTIME_OPTIONS);
  await proxy.start();
  const cleanup = (source2 = "proxy-signal") => {
    logLifecycleEvent(source2, "Embedded Maker proxy received shutdown signal; exiting.");
    proxy.cleanup();
    process.exit(0);
  };
  installProxyStdinExitHandler(proxy);
  installParentDeathWatchdog2(proxy);
  process.on("SIGINT", () => cleanup("proxy-sigint"));
  process.on("SIGTERM", () => cleanup("proxy-sigterm"));
}
function printHelp2() {
  process.stdout.write(
    [
      "Usage:",
      "  taptap-maker                         Start MCP server mode",
      "  taptap-maker init [--app-id ID] [--target-dir DIR] [--pat PAT]",
      "                     [--create --name NAME]",
      "                     [--skip-confirm] [--skip-mcp-install]",
      "                     [--launcher self|npx]",
      "                     [--json]",
      "",
      "Init flows:",
      "  Standard init/clone/download flow: run `taptap-maker init`; the CLI shows",
      "    the Maker app list, then the user chooses an existing app or 0/new.",
      "  Create-new-project flow: add `--create --name NAME` only when the user",
      "    clearly asks to create a new Maker project; NAME is the requested project name.",
      "",
      "  taptap-maker doctor [--target-dir DIR] [--json]",
      "  taptap-maker console serve  # launch from outside the AI IDE on Windows",
      "  taptap-maker console open [--target-dir PROJECT_ABSOLUTE_PATH] [--no-open] [--json]",
      "  taptap-maker console status|stop [--json]",
      "  taptap-maker canvas capabilities",
      `  ${IMAGE_CLI_USAGE}`,
      "  taptap-maker canvas list|pages|templates --target-dir PROJECT_ABSOLUTE_PATH",
      "  taptap-maker canvas ui-archives --target-dir PATH [--canvas-id ID]",
      "  taptap-maker canvas model-settings",
      "  taptap-maker canvas archive-ui --target-dir PATH --canvas-id ID",
      "  taptap-maker canvas <action> --target-dir PATH --page-id ID --canvas-id ID --revision N --input-file FILE",
      "  taptap-maker canvas status|wait --target-dir PATH --operation-id ID",
      "  taptap-maker build --target-dir PROJECT_ABSOLUTE_PATH [--json]",
      "  taptap-maker qrcode --target-dir PROJECT_ABSOLUTE_PATH [--confirmed-screen-orientation landscape|portrait] [--json]",
      "  taptap-maker python doctor [--json]",
      "  taptap-maker python setup [--json]",
      "  taptap-maker python path [--json]",
      "  taptap-maker lua-lsp doctor [--json]",
      "  taptap-maker lua-lsp setup [--json]",
      "  taptap-maker apps [--pat PAT] [--all] [--json]",
      "                     # --pat warns: PAT appears in ps/history",
      "  taptap-maker login [--json]",
      "  taptap-maker pat set [--pat-stdin] [--json]",
      "  taptap-maker pat set [PAT|--pat PAT] [--json]  # fallback; warns: PAT appears in ps/history",
      "  taptap-maker install [--launcher self|npx] [--json]  # alias for mcp install",
      "  taptap-maker mcp install [--launcher self|npx] [--json]",
      "  taptap-maker mcp verify [--mode npx|self] [--json]",
      "  taptap-maker mcp report [--ide CLIENT] [--target-dir DIR]",
      "                            [--context-stdin] [--consent] [--json]",
      "                            # Run only after the user agrees to submit",
      "  taptap-maker agents update [--target-dir DIR] [--json]",
      "  taptap-maker plugin inspect --client codex|workbuddy [--json]",
      "  taptap-maker plugin migrate --client codex|workbuddy --confirm [--json]",
      "  taptap-maker plugin restore --client codex|workbuddy --confirm [--json]",
      "  taptap-maker upgrade [--launcher self|npx] [--target-dir DIR] [--json]",
      "  taptap-maker dev-kit update [--target-dir DIR] [--json]",
      "  taptap-maker user-skills pull [--target-dir DIR] [--json]",
      "  taptap-maker logs watch [--target-dir DIR] [--interval 5s] [--reset] [--json]",
      "  taptap-maker preview install|prepare|start|run|status|refresh|stop|logs|screenshot|validate|check",
      "                       --target-dir PROJECT_ABSOLUTE_PATH [--json] [--duration-ms 1000..600000]",
      "                       [--runtime ABSOLUTE_EXECUTABLE] [--expectation TEXT] [--update]",
      "                       [--cursor N --session-id ID --reload-id N] [--limit 1..500]",
      "  preview validate: [--mode validate|screenshot|both] [--entry SCRIPT.lua]",
      "                    [--network]  # required for network/server projects; allocates a test server",
      "                    [--screenshot-frame N] [--validate-frames N] [--validate-timeout 1..580]",
      "                    [--validate-test SCRIPT.lua] [--validate-spike-threshold MS] [--nosound]",
      "                    [--output-dir /absolute/acceptance-directory]",
      "                    [--width 100..4096 --height 100..4096]",
      "  Capture requires an explicit frame. COMPLETED means evidence collected, not game PASS.",
      "  Local preview never commits or remotely builds; refresh restarts and loses memory state.",
      "",
      "MCP install and verify default to a stable self runtime under the Maker home directory.",
      "Use --launcher npx only when npm startup is explicitly required; released builds pin",
      "the exact @taptap/maker version and persist a dedicated writable npm cache.",
      "",
      "MCP install defaults:",
      "  Automatically detects supported installed IDEs and writes their Maker MCP configs.",
      "  Legacy --ide/--register-mcp selection remains accepted for existing automation only.",
      "",
      "Windows note:",
      "  The default self launcher uses absolute node.exe plus a stable versioned maker.js.",
      "  Explicit npx mode uses absolute node.exe + npm-cli.js and never persists .cmd wrappers.",
      ""
    ].join("\n")
  );
}
main().catch((error2) => {
  logCrash("main.catch", error2);
  safeWriteStderr(`❌ ${formatCliError(error2)}
`);
  process.exit(1);
});
function installCrashLogging() {
  installStdioErrorHandler(process.stdout, "stdout-error");
  installStdioErrorHandler(process.stderr, "stderr-error");
  installStdinErrorHandler();
  let handlingFatalError = false;
  process.on("uncaughtException", (error2) => {
    logCrash("uncaughtException", error2);
    if (isDisconnectedStdioError(error2)) {
      logLifecycleEvent("uncaughtException-stdio-closed", "Maker stdio disconnected; exiting.");
      process.exit(0);
    }
    if (handlingFatalError) {
      logCrash("uncaughtException-recursive", error2);
      process.exit(1);
    }
    handlingFatalError = true;
    safeWriteStderr(`❌ Uncaught Maker MCP error: ${error2.message}
`);
    handlingFatalError = false;
  });
  process.on("unhandledRejection", (reason) => {
    logCrash("unhandledRejection", reason);
    if (isDisconnectedStdioError(reason)) {
      logLifecycleEvent("unhandledRejection-stdio-closed", "Maker stdio disconnected; exiting.");
      process.exit(0);
    }
    if (handlingFatalError) {
      logCrash("unhandledRejection-recursive", reason);
      process.exit(1);
    }
    handlingFatalError = true;
    safeWriteStderr(
      `❌ Unhandled Maker MCP rejection: ${reason instanceof Error ? reason.message : String(reason)}
`
    );
    handlingFatalError = false;
  });
}
function installStdioErrorHandler(stream, source2) {
  stream.on("error", (error2) => {
    logCrash(source2, error2);
    if (isDisconnectedStdioError(error2)) {
      process.exit(0);
    }
  });
}
function installStdinErrorHandler() {
  process.stdin.on("error", (error2) => {
    logCrash("stdin-error", error2);
    if (isDisconnectedStdioError(error2)) {
      logLifecycleEvent("stdin-error-disconnected", "Maker stdin became unreadable; exiting.");
      process.exit(0);
    }
  });
}
function safeWriteStderr(message) {
  try {
    process.stderr.write(message);
  } catch (error2) {
    logCrash("stderr-write-failed", error2);
    if (isDisconnectedStdioError(error2)) {
      process.exit(0);
    }
  }
}
function logCrash(source2, error2) {
  try {
    appendMakerCrashLog(source2, error2);
  } catch {
  }
}
